class Stack:
    """Stack data structure implementation."""

    def __init__(self):
        self.items = []

    def push(self, item):
        """Push an item onto the stack."""
        self.items.append(item)

    def pop(self):
        """Pop an item from the stack. Raise IndexError if stack is empty."""
        if not self.is_empty():
            return self.items.pop()
        raise IndexError("pop from empty stack")

    def peek(self):
        """Get the top item of the stack without removing it. Raise IndexError if stack is empty."""
        if not self.is_empty():
            return self.items[-1]
        raise IndexError("peek from empty stack")

    def is_empty(self):
        """Check if the stack is empty."""
        return len(self.items) == 0


class Queue:
    """Queue data structure implementation."""

    def __init__(self):
        self.items = []

    def enqueue(self, item):
        """Add an item to the end of the queue."""
        self.items.append(item)

    def dequeue(self):
        """Remove and return the first item from the queue. Raise IndexError if queue is empty."""
        if not self.is_empty():
            return self.items.pop(0)
        raise IndexError("dequeue from empty queue")

    def front(self):
        """Get the first item of the queue without removing it. Raise IndexError if queue is empty."""
        if not self.is_empty():
            return self.items[0]
        raise IndexError("front from empty queue")

    def is_empty(self):
        """Check if the queue is empty."""
        return len(self.items) == 0


def stack_queue(operation, *args):
    """Primary function to handle Stack and Queue operations."""
    if operation == "stack":
        stack = Stack()
        for arg in args:
            if isinstance(arg, tuple):
                method, value = arg
