def validate_email(email):
    """Validate an email address format without using regex."""
    if "@" not in email:
        return False

    local_part, domain = email.split("@")

    if len(local_part) == 0 or len(domain) == 0:
        return False

    if "." not in domain:
        return False

    subdomains = domain.split(".")

    if len(subdomains) < 2:
        return False

    for char in local_part:
        if not (char.isalnum() or char in "!#$%&'*+-/=?^_`{|}~."):
            return False

    for char in subdomains[1:]:
        if not char.isalpha():
            return False

    return True

